import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";import"./chunks/assets.CKUgKlCM.js";var i=JSON.parse(`{"title":"Multilingual templates","description":"","frontmatter":{},"headers":[],"relativePath":"finding-templates/multilingual.md","filePath":"finding-templates/multilingual.md","lastUpdated":1781102819000}`),a={name:`finding-templates/multilingual.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /finding-templates/multilingual.md for this page in Markdown format</div><h1 id="multilingual-templates" tabindex="-1">Multilingual templates <a class="header-anchor" href="#multilingual-templates" aria-label="Permalink to “Multilingual templates”">​</a></h1><p>Templates can contain texts for multiple languages. This enabled you to manage all data of a template in one place even when it is translated in multiple languages.</p><p><img src="/images/templates_multilanguage.gif" alt="Multilingual finding templates" width="998" height="623"></p><p>Each template has a (required) main language and (optionally) multiple translations. The main language defines all fields that are required in the template (e.g. title, cvss, description, recommendation, references, etc.). Translations can override language-specific fields (e.g. title, description, recommendation, etc.). Fields that are not overridden are inherited from the main language (e.g. cvss, references).</p><p>This approach allows for maximum flexibility in template translations, since you can translate each field separately for each language.</p><p>Consider following scenario:</p><p>You are writing a template in English, German and Dutch, where English is the main language and German and Dutch are translations. In the English template you fill the text fields for title, description and recommendation with vulnerability descriptions (and some TODO markers to insert screenshots and pentest project specific details). Additionally you define the language-independent fields CVSS and references.</p><p>In the German and Dutch translations you only translate the title, description and recommendation fields need to be translated. The CVSS and references fields are inherited from the English template.</p><p>Let&#39;s consider you have found a great blog post describing the vulnerability in detail and want to use it as a reference in your report. However, the blog post is only available in German, so you cannot use the for the English and Dutch template. It is still possible to use them just for the German translation, by overriding the references field in the German translation. The Dutch translation still inherits the English references, but the German translation contains the additional reference.</p>`,10)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};